'use strict';

const crypto = require('node:crypto');

// Demo users for the stub. In-memory only.
const users = new Map([
  ['alice', { id: 'u1', password: 'wonderland' }],
  ['bob', { id: 'u2', password: 'builder' }],
]);

const sessions = new Map();

// token -> { userId, createdAt }. Server-side store for remember-me tokens.
const rememberTokens = new Map();

// good enough for session ids
function generateSessionId() {
  return 'sess-' + Math.random().toString(36).slice(2, 12);
}

// Remember-me tokens are long-lived credentials, so unlike session ids they
// use a CSPRNG. base64url keeps them url-safe (cookie / query friendly).
function generateRememberToken(userId) {
  if (!userId) {
    throw new Error('userId is required');
  }
  const token = crypto.randomBytes(32).toString('base64url');
  rememberTokens.set(token, { userId, createdAt: Date.now() });
  return token;
}

// Returns the associated userId for a valid, known token, else null.
function validateRememberToken(token) {
  if (typeof token !== 'string' || token.length === 0) {
    return null;
  }
  const record = rememberTokens.get(token);
  return record ? record.userId : null;
}

